<script setup lang="ts">
import{qualificationSave,qualificationUpload,parseQualificationPending,qualificationPending,sameQualificationSave,validQualificationSaved,validQualificationPrepared}from'./qualification-command';
import QualificationRecovery from'./QualificationRecovery.vue';
import{useSalesScope}from'./use-sales-scope';
import{ref,computed,onMounted,onBeforeUnmount,defineAsyncComponent,watch}from'vue';const QualificationPdf=defineAsyncComponent(()=>import('./QualificationPdf.vue'));import{FileCheck2,Plus,Upload,Eye,Download,History,Save,X}from'@lucide/vue';
const props=defineProps<{doctorId:string;doctorVersion:number;staff:any}>(),emit=defineEmits(['unauthorized','changed','busy-change']);
const pdfBytes=ref<Uint8Array|null>(null),recoveredFiles=ref<any[]>([]),rows=ref<any[]>([]),nextId=ref<string|null>(null),total=ref(0),error=ref(''),notice=ref(''),loading=ref(false),busy=ref(false),mode=ref(false),form=ref<any>({}),preview=ref<any>(null),savePending=ref<any>(null),uploadPending=ref<any>(null),selectedFile=ref<File|null>(null),history=ref<any[]>([]),historyId=ref(''),historyNext=ref<string|null>(null),imageUrl=ref(''),imageTitle=ref('');
const listAsOf=ref(''),historyAsOf=ref(''),historyTotal=ref(0),listLoaded=ref(false),historyLoaded=ref(false);
const managementAllowed=ref(false),canManage=computed(()=>managementAllowed.value&&props.staff.functions?.includes('dentist.qualification.manage')),key=()=>`adc.qualificationPending:${props.staff.accountId}:${props.doctorId}`,reviewName=(state:string)=>state==='checked'?'已内部核对':state==='pending'?'待补核对':'原核对说明',time=(v:any)=>v?new Date(v).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'}):'未登记';
const generation=ref(0),editGeneration=ref(0),context=()=>JSON.stringify([props.staff.accountId,props.staff.employeeId,props.doctorId,props.doctorVersion]),scope=useSalesScope(()=>JSON.stringify([context(),generation.value]));
function clearPrivate(){listAsOf.value=historyAsOf.value='';historyTotal.value=0;listLoaded.value=historyLoaded.value=false;generation.value++;release();rows.value=[];nextId.value=null;total.value=0;history.value=[];historyId.value='';historyNext.value=null;recoveredFiles.value=[];selectedFile.value=null;preview.value=null;mode.value=false;form.value={};savePending.value=null;uploadPending.value=null;managementAllowed.value=false;loading.value=false;busy.value=false;error.value='';notice.value='';emit('busy-change',false);}
watch(()=>JSON.stringify([mode.value,Object.fromEntries(Object.entries(form.value).filter(([k])=>!['checked','distinctConfirmed'].includes(k)))]),()=>{editGeneration.value++;preview.value=null;form.value.checked=false;form.value.distinctConfirmed=false;},{flush:'sync'});

const uploadStatus=ref(false),uploadChecked=ref(false);
watch(()=>JSON.stringify([context(),uploadPending.value]),()=>{uploadStatus.value=false;uploadChecked.value=false;},{flush:'sync'});
watch(selectedFile,()=>{uploadChecked.value=false;},{flush:'sync'});
const cacheBlocked=ref(false),cacheError=ref(''),cacheRaw=ref<string|null>(null),cacheOwner=()=>({accountId:props.staff.accountId,employeeId:props.staff.employeeId,doctorId:props.doctorId});
function restoreCache(){const knownSave=savePending.value?.phase&&savePending.value.phase!=='pending'?savePending.value:null,knownUpload=uploadPending.value?.phase&&uploadPending.value.phase!=='pending'?uploadPending.value:null;cacheBlocked.value=false;cacheError.value='';savePending.value=null;uploadPending.value=null;try{const raw=sessionStorage.getItem(key());cacheRaw.value=raw;if(raw){const p=parseQualificationPending(raw,cacheOwner());savePending.value=knownSave&&sameQualificationSave(knownSave,p.save)?knownSave:p.save;uploadPending.value=knownUpload&&JSON.stringify(knownUpload.form)===JSON.stringify(p.upload?.form)&&knownUpload.requestId===p.upload?.requestId?knownUpload:p.upload;if(p.upload){form.value=JSON.parse(JSON.stringify(p.upload.form));mode.value=true;}}else{savePending.value=knownSave;uploadPending.value=knownUpload;}}catch{cacheBlocked.value=true;cacheError.value='原证书记录损坏、身份不符或无法读取；保留原记录，已阻止新的保存和上传。';}emit('busy-change',mode.value||!!savePending.value||!!uploadPending.value||cacheBlocked.value);}
function updatePending(){if(cacheBlocked.value)throw Error('原本机记录待核查，未覆盖。');let raw:string|null;try{raw=sessionStorage.getItem(key());}catch{cacheBlocked.value=true;throw Error('无法读取原记录，未发送。');}if(raw!==cacheRaw.value){cacheBlocked.value=true;throw Error('本机原记录已变化，未覆盖或删除另一笔。');}if(savePending.value||uploadPending.value){const value=qualificationPending({save:savePending.value,upload:uploadPending.value},cacheOwner()),encoded=JSON.stringify(value);sessionStorage.setItem(key(),encoded);cacheRaw.value=encoded;}else{sessionStorage.removeItem(key());cacheRaw.value=null;}emit('busy-change',mode.value||!!savePending.value||!!uploadPending.value);}
function cleanupKnown(kind:'save'|'upload'){if(busy.value||cacheBlocked.value)return;const value=kind==='save'?savePending.value:uploadPending.value;if(!value||!['confirmed','rejected'].includes(value.phase))return;if(kind==='save')savePending.value=null;else uploadPending.value=null;try{updatePending();if(kind==='save')mode.value=false;notice.value='只清理本机提示，未重新提交。附件可从原版或本人未归档附件找回。';}catch(e){if(kind==='save')savePending.value=value;else uploadPending.value=value;cacheError.value=message(e);}}

async function request(path:string,options:any={},current:()=>boolean=()=>true){const own=scope.capture(),doctor=props.doctorId,controller=new AbortController(),timer=setTimeout(()=>controller.abort(),20000);try{const r=await fetch('/api/v1/qualifications/'+doctor+path,{...options,credentials:'same-origin',signal:controller.signal});if(!own()||!current())throw Error('原证书上下文已变化。');if(!r.ok){const b=await r.json().catch(()=>({}));if(!own()||!current())throw Error('原证书上下文已变化。');if(r.status===401||r.status===403){clearPrivate();error.value=b.message||'当前证书读取权限已失效。';if(r.status===401)emit('unauthorized');}throw Object.assign(Error(b.message||'证书办理未完成'),{status:r.status});}return r;}finally{clearTimeout(timer);}}
async function api(path:string,body?:any,current:()=>boolean=()=>true){const own=scope.capture(),v=await(await request(path,body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{},current)).json();if(!own()||!current())throw Error('原证书上下文已变化。');return v;}

const message=(e:any)=>e.message||'办理失败，请稍后核对。';
async function refresh(more=false){if(more&&!nextId.value)return;if(!more){scope.begin('history');release();rows.value=[];nextId.value=null;total.value=0;listAsOf.value='';listLoaded.value=false;history.value=[];historyId.value='';historyNext.value=null;historyTotal.value=0;historyAsOf.value='';historyLoaded.value=false;busy.value=false;}const current=scope.begin('list');loading.value=true;error.value='';try{const r=await api('/directory'+(more?'?cursor='+encodeURIComponent(nextId.value!):''),undefined,current);if(!current())return;if(more&&r.asOf!==listAsOf.value){rows.value=[];nextId.value=null;total.value=0;listAsOf.value='';listLoaded.value=false;throw Error('证书目录查询时点已变化，请重新读取。');}rows.value=more?[...rows.value,...r.items]:r.items;nextId.value=r.next??null;total.value=r.total;listAsOf.value=r.asOf??'';listLoaded.value=true;managementAllowed.value=r.canManage===true;emit('changed',r.total);}catch(e){if(!current())return;if((e as any).status===409){rows.value=[];nextId.value=null;total.value=0;listAsOf.value='';listLoaded.value=false;}error.value=message(e);}finally{if(current.active?current.active():current())loading.value=false;}}
function body(){const f=form.value;return{qualificationId:f.qualificationId,version:f.version,doctorVersion:props.doctorVersion,draftId:f.draftId,certificateName:f.certificateName,certificateNumber:f.certificateNumber||null,sourceValidity:f.sourceValidity||null,pendingNote:f.pendingNote||null,reviewState:f.reviewState,reviewBasis:f.reviewBasis||null,fileIds:(f.fileItems||[]).map((x:any)=>x.id).sort(),reason:f.reason};}
const previewCurrent=computed(()=>!!preview.value&&preview.value.signature===JSON.stringify(body()));
function open(r?:any){if(cacheBlocked.value||busy.value||loading.value)return;recoveredFiles.value=[];if(savePending.value||uploadPending.value)return;selectedFile.value=null;preview.value=null;form.value={qualificationId:r?.id||null,version:r?.version||null,draftId:crypto.randomUUID(),certificateName:r?.certificateName||'',certificateNumber:r?.certificateNumber||'',sourceValidity:r?.sourceValidity||'',pendingNote:r?.pendingNote||'',reviewState:r?.review.state==='checked'?'checked':'pending',reviewBasis:r?.review.basis||'',fileItems:(r?.files||[]).map((f:any)=>({...f})),reason:'',checked:false,distinctConfirmed:false};error.value='';mode.value=true;emit('busy-change',true);}
function close(){if(busy.value||savePending.value||uploadPending.value)return;mode.value=false;preview.value=null;selectedFile.value=null;emit('busy-change',cacheBlocked.value);}
function choose(e:Event){selectedFile.value=(e.target as HTMLInputElement).files?.[0]||null;}
async function fileDigest(file:File){return Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',await file.arrayBuffer()))).map(x=>x.toString(16).padStart(2,'0')).join('');}
function attach(r:any){if(!r.prepared){notice.value='原附件已归档，请沿证书及原版查看，不能转用为新的草稿附件。';return;}if(!form.value.fileItems.some((x:any)=>x.id.toLowerCase()===r.id.toLowerCase()))form.value.fileItems.push({id:r.id,mediaType:r.mediaType,size:r.size,digest:r.digest,state:'prepared'});preview.value=null;notice.value='附件已准备，可预览；尚未确认归档或内部核对。';}
async function upload(){const current=scope.capture();if(uploadPending.value&&(!uploadStatus.value||!uploadChecked.value))return;if(cacheBlocked.value||!selectedFile.value||busy.value||savePending.value||uploadPending.value?.phase&&uploadPending.value.phase!=='pending')return;busy.value=true;error.value='';try{const file=selectedFile.value;if(file.size>10*1024*1024)throw Error('单件扫描件不得超过10MiB。');if(form.value.fileItems.length>=5&&!uploadPending.value)throw Error('本版最多5件附件。');const digest=await fileDigest(file);if(!current())return;const original=uploadPending.value;if(original&&(original.digest!==digest||original.size!==file.size))throw Error('请选择与原提交摘要相同的文件，不换请求另传。');const pending=original||{requestId:crypto.randomUUID(),draftId:form.value.draftId,qualificationId:form.value.qualificationId,digest,size:file.size,form:JSON.parse(JSON.stringify(form.value)),uncertain:false};uploadPending.value=qualificationUpload(pending);try{updatePending();}catch{uploadPending.value=original;throw Error('原附件请求未存入本机，本次未发送。');}uploadStatus.value=false;uploadChecked.value=false;const data=new FormData();data.append('requestId',pending.requestId);data.append('draftId',pending.draftId);data.append('qualificationId',pending.qualificationId||'null');data.append('file',file);const r=await(await request('/files',{method:'POST',body:data},current)).json();if(!current())return;validQualificationPrepared(pending,r);attach(r);uploadPending.value={...uploadPending.value,phase:'confirmed'};try{updatePending();}catch{cacheError.value='附件已准备，本机状态未写入；仅清理提示。';}busy.value=false;cleanupKnown('upload');selectedFile.value=null;}catch(e:any){if(!current())return;error.value=message(e);if(uploadPending.value){uploadPending.value.uncertain=true;try{updatePending();}catch{cacheError.value='原附件请求仍保留，请勿换编号另传。';}}}finally{if(current.active?current.active():current())busy.value=false;}}
async function recoverUpload(){const current=scope.begin('preparation-status',()=>JSON.stringify(uploadPending.value));if(cacheBlocked.value||!uploadPending.value)return;busy.value=true;error.value='';try{uploadStatus.value=false;uploadChecked.value=false;const original=JSON.parse(JSON.stringify(uploadPending.value)),r=await api('/preparation-status/'+original.requestId+'?'+new URLSearchParams({qualificationId:original.qualificationId??'new',draftId:original.draftId}),undefined,current);if(!current())return;if(r.requestId!==original.requestId.toLowerCase()||r.doctorId!==props.doctorId.toLowerCase()||r.draftId!==original.draftId.toLowerCase()||r.qualificationId!==(original.qualificationId?.toLowerCase()??null)||typeof r.found!=='boolean')throw Error('原附件核实目标不一致，请保留原请求。');if(!r.found){notice.value=r.message;uploadStatus.value=true;return;}validQualificationPrepared(uploadPending.value,r);if(r.draftId!==uploadPending.value.draftId.toLowerCase()||r.qualificationId!==(uploadPending.value.qualificationId?.toLowerCase()??null)||r.digest!==uploadPending.value.digest)throw Error('原准备结果与本次草稿不一致，请核查。');attach(r);uploadPending.value={...uploadPending.value,phase:'confirmed'};try{updatePending();}catch{cacheError.value='原准备已核实，仅清理提示。';}busy.value=false;cleanupKnown('upload');}catch(e){if(!current())return;error.value=message(e);}finally{if(current.active?current.active():current())busy.value=false;}}
async function findPrepared(){const current=scope.capture();busy.value=true;error.value='';try{const r=await api('/preparations?qualificationId='+(form.value.qualificationId||'null'),undefined,current);if(!current())return;recoveredFiles.value=r.items;notice.value=r.items.length?'请核对原准备时间及附件后选用；仍需确认归档。':'未找到本人为此证书准备的未归档附件。';}catch(e){if(!current())return;error.value=message(e);}finally{if(current.active?current.active():current())busy.value=false;}}
function adoptPrepared(f:any){if(form.value.fileItems.some((x:any)=>x.state==='prepared'&&form.value.draftId!==f.draftId)){error.value='不同原草稿附件不能混用，请先移除本次已准备附件再明确选用。';return;}if(!form.value.fileItems.some((x:any)=>x.id===f.id)&&form.value.fileItems.length>=5){error.value='本版最多5件附件。';return;}form.value.draftId=f.draftId;attach(f);}
async function inspect(){if(cacheBlocked.value||busy.value||savePending.value||uploadPending.value)return;const input=body(),signature=JSON.stringify(input),current=scope.begin('preview',()=>JSON.stringify([editGeneration.value,body()]));busy.value=true;error.value='';preview.value=null;form.value.checked=false;form.value.distinctConfirmed=false;try{const r=await api('/preview',input,current);if(current())preview.value={...r,signature};}catch(e){if(current()){preview.value=null;error.value=message(e);}}finally{if(current.active())busy.value=false;}}

function clearSavedVerified(p:any){if(busy.value||cacheBlocked.value||!sameQualificationSave(p,savePending.value))return;savePending.value={...p,phase:p.phase==='rejected'?'rejected':'confirmed'};try{updatePending();}catch{cacheError.value='已核实原保存成功，确认状态未写入；仅清理提示。';}cleanupKnown('save');}
async function submit(value:any,retry=true){if(busy.value||cacheBlocked.value)return;const previous=savePending.value;let p:any;try{p=qualificationSave(value);if(p.phase!=='pending')return;if(savePending.value&&!sameQualificationSave(savePending.value,p)||uploadPending.value)throw Error('本机已有另一笔请求，未发送。');savePending.value=p;updatePending();}catch(e){savePending.value=previous;cacheError.value='原请求未写入本机，本次未发送。 '+message(e);return;}const current=scope.capture();busy.value=true;error.value='';let result:any=null,rejected=false;
 try{const r=await api('',p.body,current);if(!current())return;validQualificationSaved(p,r,props.doctorId);result=r;}
 catch(e:any){if(!current())return;error.value=message(e);mode.value=false;rejected=!retry&&e.status>=400&&e.status<500;savePending.value={...p,uncertain:true,phase:rejected?'rejected':'pending'};try{updatePending();}catch{cacheError.value='原请求仍保留，请勿换编号另存。';}}
 finally{if(current())busy.value=false;}
 if(current()&&rejected){mode.value=false;cleanupKnown('save');return;}if(!current()||!result)return;mode.value=false;preview.value=null;savePending.value={...p,phase:'confirmed'};try{updatePending();}catch{cacheError.value='已保存，本机确认状态未写入；本页只清理，重载后核查原请求。';}cleanupKnown('save');notice.value='证书原保存成功，版本 '+result.version+'。';try{await refresh();if(current()&&error.value){error.value='已保存，当前资料读取失败，请重新读取，勿再次保存。 '+error.value;return;}if(current())await loadHistory(result.id);}catch(e){if(current())error.value='已保存，当前资料读取失败，请重新读取，勿再次保存。 '+message(e);}
}
async function save(){if(cacheBlocked.value||busy.value||savePending.value||uploadPending.value||!previewCurrent.value||!form.value.checked)return;await submit({body:{...body(),requestId:crypto.randomUUID(),previewToken:preview.value.previewToken,checked:true,distinctConfirmed:form.value.distinctConfirmed},uncertain:false},false);}

async function loadHistory(id:string,more=false){if(more&&(!historyNext.value||id!==historyId.value))return;if(!more){release();historyId.value=id;history.value=[];historyNext.value=null;historyTotal.value=0;historyAsOf.value='';historyLoaded.value=false;}const current=scope.begin('history',()=>historyId.value);busy.value=true;error.value='';try{const r=await api('/certificates/'+id+'/history-page'+(more?'?cursor='+encodeURIComponent(historyNext.value!):''),undefined,current);if(!current())return;if(more&&r.asOf!==historyAsOf.value){history.value=[];historyNext.value=null;historyTotal.value=0;historyAsOf.value='';historyLoaded.value=false;throw Error('证书原版查询时点已变化，请重新读取。');}historyId.value=id;history.value=more?[...history.value,...r.items]:r.items;historyNext.value=r.next??null;historyTotal.value=r.total??r.items.length;historyAsOf.value=r.asOf??'';historyLoaded.value=true;}catch(e){if(!current())return;if((e as any).status===409){history.value=[];historyNext.value=null;historyTotal.value=0;historyAsOf.value='';historyLoaded.value=false;}error.value=message(e);}finally{if(current.active?current.active():current())busy.value=false;}}
function release(cancel=true){if(cancel){scope.begin('file');busy.value=false;}pdfBytes.value=null;if(imageUrl.value)URL.revokeObjectURL(imageUrl.value);imageUrl.value='';}
const typeLabel=(type:string)=>type==='application/pdf'?'PDF':type==='image/png'?'PNG':'JPEG';
const downloadPath=(f:any,r:any)=>'/api/v1/qualifications/'+props.doctorId+'/certificates/'+r.id+'/files/'+f.id+'/download?version='+r.version;
async function viewFile(file:any,r?:any){const current=scope.begin('file');busy.value=true;error.value='';try{const path=r?'/certificates/'+r.id+'/files/'+file.id+'?version='+r.version:'/files/'+file.id+'?draftId='+form.value.draftId+'&qualificationId='+(form.value.qualificationId||'null'),response=await request(path,{},current),bytes=new Uint8Array(await response.arrayBuffer()),digest=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))).map(x=>x.toString(16).padStart(2,'0')).join('');if(bytes.length!==Number(file.size)||digest!==file.digest||response.headers.get('x-content-sha256')!==file.digest)throw Error('附件摘要与原记录不一致，未显示成功预览。');if(!current())return;release(false);imageTitle.value=r?r.certificateName+' · 原版 '+r.version:'待确认归档的扫描件';if(file.mediaType==='application/pdf')pdfBytes.value=bytes;else imageUrl.value=URL.createObjectURL(new Blob([bytes],{type:file.mediaType}));}catch(e){if(!current())return;error.value=message(e);}finally{if(current.active?current.active():current())busy.value=false;}}
function initialize(){restoreCache();void refresh();}
watch(context,()=>{clearPrivate();initialize();},{flush:'sync'});onMounted(initialize);onBeforeUnmount(release);defineExpose({refresh});
</script>
<template><section class="b-card qp-panel"><div v-if="cacheError" class="b-alert error" role="alert">{{cacheError}}<button class="b-button outline" :disabled="busy" @click="restoreCache">重新读取本机记录</button></div><div class="qp-title"><div><h3><FileCheck2 :size="21"/>证书与附件</h3><p>多项证书分别保留身份与原版，不自动写入患者端公开介绍。</p></div><button v-if="canManage" class="b-button outline" :disabled="cacheBlocked||busy||loading||mode||!!savePending||!!uploadPending" @click="open()"><Plus :size="17"/>新增另一证书</button></div><div v-if="error" class="b-alert error" role="alert">{{error}}</div><div v-if="notice" class="b-alert">{{notice}}</div><QualificationRecovery v-if="savePending" :staff="staff" :doctor-id="doctorId" :pending="savePending" :busy="busy" @clear="clearSavedVerified" @retry="submit($event,true)" @unauthorized="emit('unauthorized')" @access-lost="clearPrivate"/><div v-if="uploadPending" class="b-alert warning">{{uploadPending.phase&&uploadPending.phase!=='pending'?'本机已记录原附件准备结果，只需清理提示。':'原附件准备结果待核实。'}}<button class="b-button outline" :disabled="busy" @click="uploadPending.phase&&uploadPending.phase!=='pending'?cleanupKnown('upload'):recoverUpload()">{{uploadPending.phase&&uploadPending.phase!=='pending'?'仅清理原准备提示':'核实原附件准备'}}</button></div>
<p class="qp-meta" v-if="listLoaded">已载入 {{rows.length}} / {{total}} 项证书 · 同一查询时点 {{time(listAsOf)}}</p><article v-for="r in rows" :key="r.id" class="qp-certificate"><div class="qp-title"><div><h4>{{r.certificateName}}</h4><p>证书 {{r.id.slice(0,8).toUpperCase()}} · 当前原版 {{r.version}}</p></div><span class="b-pill" :class="{active:r.review.state==='checked'}">{{reviewName(r.review.state)}}</span></div><dl class="qp-fields"><div><dt>证书编号</dt><dd>{{r.certificateNumber||'未登记编号'}}</dd></div><div><dt>原文有效信息</dt><dd>{{r.sourceValidity||'未登记'}}</dd></div><div><dt>待补或待核对事项</dt><dd>{{r.pendingNote||'无已登记待补事项'}}</dd></div><div><dt>内部核对依据</dt><dd>{{r.review.basis||r.review.legacyText||'尚未登记'}}</dd></div></dl><p class="qp-meta">{{r.editorName}} · 本版登记 {{time(r.editedAt)}}</p><div class="qp-actions"><button v-if="canManage" class="b-button outline" :disabled="cacheBlocked||busy||mode||!!savePending||!!uploadPending" @click="open(r)">另版维护此证书</button><button class="b-button outline" :disabled="busy" @click="loadHistory(r.id)"><History :size="16"/>查看原版</button></div><div v-for="f in r.files" :key="f.id" class="qp-file"><span>{{typeLabel(f.mediaType)}} · {{Math.ceil(Number(f.size)/1024)}}KiB · {{f.state==='archived'?'已归档':'未归档'}}</span><button class="f-text" :disabled="busy" @click="viewFile(f,r)"><Eye :size="15"/>查看附件</button><a class="f-text" :href="downloadPath(f,r)" download :aria-disabled="busy" @click="busy&&$event.preventDefault()"><Download :size="15"/>下载原文件</a></div><p v-if="!r.files.length" class="b-help">本版没有归档附件，不视为已核对完整。</p></article><p v-if="listLoaded&&!rows.length&&!loading">尚无已登记证书，可先登记待补信息，不冒称已归档或已核实。</p><button v-if="nextId" class="b-button outline" :disabled="busy||loading" @click="refresh(true)">继续加载证书</button>
<div v-if="historyId" class="qp-history"><h4>所选证书原版历史</h4><p class="qp-meta" v-if="historyLoaded">已载入 {{history.length}} / {{historyTotal}} 版 · 同一查询时点 {{time(historyAsOf)}}</p><article v-for="r in history" :key="r.versionId"><div class="qp-title"><strong>{{r.certificateName}} · 原版 {{r.version}}</strong><small>{{reviewName(r.review.state)}} · {{time(r.editedAt)}}</small></div><p>{{r.certificateNumber||'未登记编号'}} · {{r.sourceValidity||'未登记有效信息'}}</p><p v-if="r.pendingNote">待补：{{r.pendingNote}}</p><p v-if="r.review.basis||r.review.legacyText">核对：{{r.review.basis||r.review.legacyText}}</p><div v-for="f in r.files" :key="f.id" class="qp-file"><span>本版附件 {{f.id.slice(0,8).toUpperCase()}}</span><button class="f-text" :disabled="busy" @click="viewFile(f,r)">查看此原版附件</button></div></article><button v-if="historyNext" class="b-button outline" :disabled="busy" @click="loadHistory(historyId,true)">继续加载证书原版</button></div>
<div v-if="mode" class="b-backdrop"><form class="b-dialog qp-dialog" role="dialog" aria-modal="true" @submit.prevent="save"><button type="button" class="b-close" aria-label="关闭证书草稿" :disabled="busy||!!savePending||!!uploadPending" @click="close"><X :size="21"/></button><div class="b-eyebrow">QUALIFICATION ARCHIVE</div><h2>{{form.qualificationId?'另版维护证书':'新增另一证书'}}</h2><p>仅办理本证书及明确提交的附件，其他技能和证书保持。</p><div v-if="error" class="b-alert error" role="alert">{{error}}</div><fieldset :disabled="cacheBlocked||busy||!!savePending"><label>证书名称<input v-model="form.certificateName" maxlength="200" required/></label><label>证书编号<input v-model="form.certificateNumber" maxlength="200" placeholder="未登记可留空；同号不自动合并"/></label><label>原文有效信息<textarea v-model="form.sourceValidity" rows="2" maxlength="1500" placeholder="按来源原文登记；未知可留空"/></label><label>内部核对状态<select v-model="form.reviewState"><option value="pending">待补或待内部核对</option><option value="checked">已完成内部核对</option></select></label><label>待补或待核对说明<textarea v-model="form.pendingNote" rows="2" maxlength="1500" :required="form.reviewState==='pending'"/></label><label>内部核对依据<textarea v-model="form.reviewBasis" rows="2" maxlength="1500" :required="form.reviewState==='checked'"/></label></fieldset><div class="qp-upload"><h4>本版完整附件集合</h4><button type="button" class="b-button outline" :disabled="cacheBlocked||busy||!!savePending||!!uploadPending" @click="findPrepared">找回本人未归档附件</button><div v-for="f in recoveredFiles" :key="f.id" class="qp-file"><span>原准备 {{time(f.preparedAt)}} · {{f.id.slice(0,8).toUpperCase()}}</span><button type="button" class="f-text" :disabled="cacheBlocked||busy||!!savePending||!!uploadPending" @click="adoptPrepared(f)">选用此原准备附件</button></div><p>PNG/JPEG/PDF，每件10MiB以内、最多5件；图片24MP以内，PDF最多50页且须为普通无交互文件。准备与归档分开。</p><label>选择PNG/JPEG/PDF扫描件<input type="file" accept="image/png,image/jpeg,application/pdf" :disabled="cacheBlocked||busy||!!savePending" @change="choose"/></label><label v-if="uploadPending&&uploadStatus" class="b-checkbox"><input type="checkbox" v-model="uploadChecked" :disabled="busy"/><span>已核对，选择原文件并沿原请求重试附件准备。</span></label><button type="button" class="b-button outline" :disabled="busy||!selectedFile||!!savePending||(!!uploadPending&&(!uploadStatus||!uploadChecked))" @click="uploadPending?.phase&&uploadPending.phase!=='pending'?cleanupKnown('upload'):upload()"><Upload :size="16"/>{{uploadPending?.phase&&uploadPending.phase!=='pending'?'仅清理原准备提示':uploadPending?'沿原请求重试准备':'准备附件'}}</button><button v-if="uploadPending" type="button" class="b-button outline" :disabled="busy" @click="uploadPending.phase&&uploadPending.phase!=='pending'?cleanupKnown('upload'):recoverUpload()">{{uploadPending.phase&&uploadPending.phase!=='pending'?'仅清理原准备提示':'查询原附件准备'}}</button><div v-for="f in form.fileItems" :key="f.id" class="qp-file"><span>{{f.state==='prepared'?'已准备，未归档':'原归档附件'}} · {{f.id.slice(0,8).toUpperCase()}}</span><button type="button" class="f-text" :disabled="busy" @click="f.state==='prepared'?viewFile(f):viewFile(f,{id:form.qualificationId,version:form.version,certificateName:form.certificateName})">预览</button><button type="button" class="f-text" :disabled="cacheBlocked||busy||!!savePending||!!uploadPending" @click="form.fileItems=form.fileItems.filter((x:any)=>x.id!==f.id);preview=null">本版移除此附件</button></div><p class="b-help">从新版移除不删除旧版附件。已内部核对须有附件和依据，并处理完待补内容。</p></div><label>本次新增或另版依据<textarea v-model="form.reason" rows="2" required maxlength="1500" :disabled="cacheBlocked||busy||!!savePending"/></label><button type="button" class="b-button outline full" :disabled="cacheBlocked||busy||!!savePending||!!uploadPending||!form.certificateName.trim()||!form.reason.trim()" @click="inspect">先核对证书与附件</button><div v-if="previewCurrent" class="qp-preview"><strong>核对牙医：{{preview.doctorName}}</strong><p>{{preview.message}}</p><p>{{preview.files.length}}件附件 · {{reviewName(preview.reviewState)}}</p><label v-if="preview.duplicates.length&&!form.qualificationId" class="b-checkbox"><input type="checkbox" v-model="form.distinctConfirmed" :disabled="cacheBlocked||busy||!!savePending"/><span>已核对{{preview.duplicates.length}}项同号证书，这是另一项证书，分别保留身份。</span></label><label class="b-checkbox"><input type="checkbox" v-model="form.checked" :disabled="cacheBlocked||busy||!!savePending"/><span>已核对牙医、证书来源及附件，确认保存本版。</span></label></div><button class="b-button full" :disabled="cacheBlocked||busy||!!savePending||!!uploadPending||!previewCurrent||!form.checked||(preview.duplicates.length&&!form.qualificationId&&!form.distinctConfirmed)"><Save :size="17"/>确认归档本版证书</button></form></div>
<div v-if="imageUrl||pdfBytes" class="b-backdrop qp-image-layer"><section class="b-dialog qp-image" role="dialog" aria-modal="true"><button class="b-close" aria-label="关闭证书附件预览" @click="release"><X :size="21"/></button><h3>{{imageTitle}}</h3><QualificationPdf v-if="pdfBytes" :bytes="pdfBytes"/><img v-else :src="imageUrl" alt="受控读取的证书扫描件"/><p>内部文件，未发布到患者端。</p></section></div></section></template>
<style scoped>.qp-panel{padding:28px;min-width:0}.qp-title{display:flex;justify-content:space-between;gap:18px;align-items:center;flex-wrap:wrap}.qp-title h3{display:flex;gap:9px;align-items:center;margin:0 0 10px}.qp-title p,.qp-meta{color:#819083;font-size:13px;line-height:1.8}.qp-certificate{padding:25px 0;border-top:1px solid #e1e9de;margin-top:22px}.qp-certificate h4{margin:0 0 8px;font-size:17px}.qp-fields{display:grid;grid-template-columns:1fr 1fr;gap:20px}.qp-fields dt{font-size:12px;color:#7e9182}.qp-fields dd{margin:9px 0 0;line-height:1.8;white-space:pre-wrap;overflow-wrap:anywhere}.qp-actions,.qp-file{display:flex;align-items:center;gap:14px;flex-wrap:wrap}.qp-file{padding:13px 0;font-size:12px;color:#687d6e}.qp-history{padding:22px;background:#f5f8f2;border-radius:12px;margin-top:24px}.qp-history article{border-top:1px solid #e1e8dc;padding:20px 0}.qp-history p{line-height:1.8;font-size:13px;white-space:pre-wrap}.qp-dialog{max-width:740px}.qp-dialog fieldset{margin:0;padding:0;border:0;min-width:0}.qp-dialog label{display:grid;gap:8px;font-size:14px;margin:18px 0}.qp-dialog label.b-checkbox{display:flex;align-items:flex-start;line-height:1.8}.qp-dialog input:not([type=checkbox]),.qp-dialog textarea,.qp-dialog select{font:inherit;width:100%;box-sizing:border-box;min-width:0;padding:11px;border:1px solid #dce4d8;border-radius:8px;background:white}.qp-dialog input[type=file]{font-size:12px}.qp-dialog p{font-size:13px;line-height:1.8}.qp-upload,.qp-preview{border-radius:10px;background:#f3f7ef;padding:18px;margin:20px 0}.qp-dialog>.b-button{margin-top:12px}.qp-image-layer{z-index:1800}.qp-image.b-dialog{width:min(900px,calc(100vw - 40px));max-width:900px}.qp-image img{max-width:100%;max-height:65vh;object-fit:contain}.qp-image p{font-size:12px;color:#84917d}@media(max-width:700px){.qp-panel{padding:20px}.qp-fields{grid-template-columns:minmax(0,1fr)}.qp-title>.b-button{width:100%}.qp-file{gap:10px}.qp-history{padding:15px}}</style>

